import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useSelector } from 'react-redux';
import NivraLogo from '../components/NivraLogo';

const AdminDashboard = () => {
  const navigate = useNavigate();
  const { user } = useSelector((state) => state.auth);
  const [stats, setStats] = useState({
    totalUsers: 0,
    activeAlerts: 0,
    totalAlerts: 0,
    resolvedAlerts: 0
  });

  useEffect(() => {
    if (!user || user.role !== 'admin') {
      navigate('/admin/login');
      return;
    }

    // Mock data for now
    setStats({
      totalUsers: 156,
      activeAlerts: 3,
      totalAlerts: 89,
      resolvedAlerts: 86
    });
  }, [user, navigate]);

  const handleLogout = () => {
    if (window.confirm('Are you sure you want to logout?')) {
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      navigate('/admin/login');
    }
  };

  return (
    <div style={{
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      {/* Header */}
      <div style={{
        background: 'rgba(255,255,255,0.95)',
        padding: '20px',
        borderBottom: '1px solid #e0e0e0',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center'
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
          <NivraLogo size={48} />
          <div>
            <h1 style={{ margin: '0', color: '#8A2BE2', fontSize: '28px', fontWeight: '700' }}>NIVRA ADMIN</h1>
            <p style={{ margin: '0', color: '#666', fontSize: '14px' }}>Administrative Dashboard</p>
          </div>
        </div>
        <button
          onClick={handleLogout}
          style={{
            background: '#ff3b30',
            color: 'white',
            border: 'none',
            padding: '10px 20px',
            borderRadius: '8px',
            cursor: 'pointer',
            fontSize: '14px',
            fontWeight: '500'
          }}
        >
          Logout
        </button>
      </div>

      {/* Main Content */}
      <div style={{ padding: '30px' }}>
        {/* Welcome */}
        <div style={{
          background: 'white',
          borderRadius: '15px',
          padding: '25px',
          marginBottom: '25px',
          boxShadow: '0 8px 25px rgba(0,0,0,0.1)'
        }}>
          <h2 style={{ margin: '0 0 10px 0', color: '#333', fontSize: '24px' }}>Welcome, {user?.fullName}</h2>
          <p style={{ margin: '0', color: '#666', fontSize: '16px' }}>Monitor and manage NIVRA safety platform</p>
        </div>

        {/* Stats Grid */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))',
          gap: '20px',
          marginBottom: '30px'
        }}>
          <div style={{
            background: 'white',
            borderRadius: '15px',
            padding: '25px',
            textAlign: 'center',
            boxShadow: '0 8px 25px rgba(0,0,0,0.1)'
          }}>
            <div style={{ fontSize: '48px', marginBottom: '10px' }}>👥</div>
            <h3 style={{ margin: '0', color: '#8A2BE2', fontSize: '32px', fontWeight: '700' }}>{stats.totalUsers}</h3>
            <p style={{ margin: '5px 0 0 0', color: '#666', fontSize: '16px' }}>Total Users</p>
          </div>

          <div style={{
            background: 'white',
            borderRadius: '15px',
            padding: '25px',
            textAlign: 'center',
            boxShadow: '0 8px 25px rgba(0,0,0,0.1)'
          }}>
            <div style={{ fontSize: '48px', marginBottom: '10px' }}>🚨</div>
            <h3 style={{ margin: '0', color: '#ff3b30', fontSize: '32px', fontWeight: '700' }}>{stats.activeAlerts}</h3>
            <p style={{ margin: '5px 0 0 0', color: '#666', fontSize: '16px' }}>Active Alerts</p>
          </div>

          <div style={{
            background: 'white',
            borderRadius: '15px',
            padding: '25px',
            textAlign: 'center',
            boxShadow: '0 8px 25px rgba(0,0,0,0.1)'
          }}>
            <div style={{ fontSize: '48px', marginBottom: '10px' }}>📊</div>
            <h3 style={{ margin: '0', color: '#007AFF', fontSize: '32px', fontWeight: '700' }}>{stats.totalAlerts}</h3>
            <p style={{ margin: '5px 0 0 0', color: '#666', fontSize: '16px' }}>Total Alerts</p>
          </div>

          <div style={{
            background: 'white',
            borderRadius: '15px',
            padding: '25px',
            textAlign: 'center',
            boxShadow: '0 8px 25px rgba(0,0,0,0.1)'
          }}>
            <div style={{ fontSize: '48px', marginBottom: '10px' }}>✅</div>
            <h3 style={{ margin: '0', color: '#34c759', fontSize: '32px', fontWeight: '700' }}>{stats.resolvedAlerts}</h3>
            <p style={{ margin: '5px 0 0 0', color: '#666', fontSize: '16px' }}>Resolved Alerts</p>
          </div>
        </div>

        {/* Admin Features */}
        <div style={{
          background: 'white',
          borderRadius: '15px',
          padding: '25px',
          boxShadow: '0 8px 25px rgba(0,0,0,0.1)'
        }}>
          <h3 style={{ margin: '0 0 20px 0', color: '#333', fontSize: '20px' }}>Admin Features</h3>
          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
            gap: '15px'
          }}>
            <button style={{
              background: '#8A2BE2',
              color: 'white',
              border: 'none',
              padding: '15px',
              borderRadius: '10px',
              fontSize: '16px',
              fontWeight: '500',
              cursor: 'pointer'
            }}>
              👥 Manage Users
            </button>
            <button style={{
              background: '#ff3b30',
              color: 'white',
              border: 'none',
              padding: '15px',
              borderRadius: '10px',
              fontSize: '16px',
              fontWeight: '500',
              cursor: 'pointer'
            }}>
              🚨 View Alerts
            </button>
            <button style={{
              background: '#007AFF',
              color: 'white',
              border: 'none',
              padding: '15px',
              borderRadius: '10px',
              fontSize: '16px',
              fontWeight: '500',
              cursor: 'pointer'
            }}>
              📍 Safety Locations
            </button>
            <button style={{
              background: '#34c759',
              color: 'white',
              border: 'none',
              padding: '15px',
              borderRadius: '10px',
              fontSize: '16px',
              fontWeight: '500',
              cursor: 'pointer'
            }}>
              📊 Analytics
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
